// Reads Your settings and your list of renewals. Checks the settings, turns each line of the list
// into a dated item, and works out whether this run came from the daily schedule or a tapped done link.
const s = $('Your settings').first().json;
const ran = name => {
  try {
    const n = $(name);
    return typeof n.isExecuted === 'boolean' ? n.isExecuted : (n.first(), true);
  } catch (e) { return false; }
};

const phone = v => {
  const raw = String(v || '').trim();
  const digits = raw.replace(/\D/g, '');
  if (raw.startsWith('+') && digits.length >= 8 && digits.length <= 15) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return '';
};
// A blank number setting falls back to the default, but 0 is kept, because 0 switches something off.
const num = (v, d) => (v === '' || v === null || v === undefined || isNaN(Number(v))) ? d : Number(v);
const yes = v => v !== false && v !== 'false';

const business_number = phone(s.business_number);
const owner_cell = phone(s.owner_cell);
if (!business_number || !owner_cell) {
  throw new Error('Your settings: business_number and owner_cell must both be phone numbers, like +1234567890.');
}
if (['+1234567890', '+1234567890'].includes(business_number) || ['+1234567890', '+1234567890'].includes(owner_cell)) {
  throw new Error('Your settings: replace the example phone numbers with your Twilio number and your cell before you publish this.');
}
const timezone = String(s.timezone || 'America/New_York').trim();
if (!DateTime.now().setZone(timezone).isValid) {
  throw new Error('Your settings: "' + timezone + '" is not a time zone n8n knows. Use a name like America/New_York.');
}
const done_links = yes(s.done_links);
const n8n_url = String(s.n8n_url || '').trim().replace(/\/+$/, '');
if (done_links && (!/^https?:\/\/[a-z0-9.-]+(:\d+)?$/i.test(n8n_url) || /your-instance/i.test(n8n_url))) {
  throw new Error('Your settings: set n8n_url to the address of your n8n, like https://yourname.app.n8n.cloud, or set done_links to false.');
}
const remind_days = [...new Set(String(s.remind_days || '60, 30, 14, 7, 3, 1, 0')
  .split(/[\s,]+/).filter(Boolean).map(Number).filter(n => Number.isInteger(n) && n >= 0))].sort((a, b) => b - a);

const cfg = {
  business_name: String(s.business_name || 'your business').trim(),
  business_number, owner_cell, timezone, n8n_url, done_links,
  remind_days: remind_days.length ? remind_days : [0],
  overdue_every_days: Math.max(0, num(s.overdue_every_days, 1)),
  monthly_outlook: yes(s.monthly_outlook),
  outlook_days: Math.max(1, num(s.outlook_days, 90)),
};

// Dates: 2027-06-30 or 6/30/2027. Repeats: yearly, monthly, quarterly, every 2 years, every 6 months, none.
const readDate = t => {
  t = String(t || '').trim();
  let d = null;
  if (/^\d{4}-\d{1,2}-\d{1,2}$/.test(t)) { const [y, m, dd] = t.split('-').map(Number); d = DateTime.fromObject({ year: y, month: m, day: dd }, { zone: timezone }); }
  else if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(t)) { const [m, dd, y] = t.split('/').map(Number); d = DateTime.fromObject({ year: y, month: m, day: dd }, { zone: timezone }); }
  return d && d.isValid ? d.toISODate() : null;
};
const UNITS = { day: 'days', days: 'days', week: 'weeks', weeks: 'weeks', month: 'months', months: 'months', year: 'years', years: 'years' };
const readRepeat = t => {
  t = String(t || '').trim().toLowerCase();
  if (!t || ['none', 'once', 'no', 'never', 'one time', '-'].includes(t)) return { ok: true, repeat: null };
  if (['yearly', 'annually', 'annual', 'every year', 'each year'].includes(t)) return { ok: true, repeat: { years: 1 } };
  if (['monthly', 'every month', 'each month'].includes(t)) return { ok: true, repeat: { months: 1 } };
  if (['quarterly', 'every quarter'].includes(t)) return { ok: true, repeat: { months: 3 } };
  const m = t.match(/^(?:every\s+)?(\d{1,3})\s+(days?|weeks?|months?|years?)$/);
  if (m && Number(m[1]) > 0) return { ok: true, repeat: { [UNITS[m[2]]]: Number(m[1]) } };
  return { ok: false, repeat: null };
};
const slug = t => String(t).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'item';

const items = [], problems = [], seen = {};
String(s.items || '').split(/\r?\n/).forEach((line, i) => {
  const text = line.trim();
  if (!text || text.startsWith('#')) return;
  const [name = '', date = '', repeat = '', ...rest] = text.split('|').map(x => x.trim());
  const note = rest.join(' | ').trim();
  const due = readDate(date);
  const r = readRepeat(repeat);
  if (!name) { problems.push('Line ' + (i + 1) + ' has no name.'); return; }
  if (!due) { problems.push('"' + name + '": I could not read the date "' + date + '". Use 2027-06-30 or 6/30/2027.'); return; }
  if (!r.ok) problems.push('"' + name + '": I could not read "' + repeat + '" as a repeat, so it will not roll forward. Use yearly, monthly, quarterly, every 2 years or none.');
  let key = slug(name);
  seen[key] = (seen[key] || 0) + 1;
  if (seen[key] > 1) key += '-' + seen[key];
  items.push({ key, name, due, repeat: r.repeat, note });
});

const tapped = ran('Done link tapped');
const query = tapped ? ($('Done link tapped').first().json.query || {}) : {};
return [{ json: { mode: tapped ? 'tap' : 'daily', cfg, items, problems, query } }];

// Runs once a day. Works out which renewals are on a reminder day, overdue, or coming up, and
// writes one text. Its memory (rolled-forward dates, done links, what already went out) is n8n
// workflow static data, which n8n keeps only while the workflow is published.
const { cfg, items, problems } = $('Read your list').first().json;
const st = $getWorkflowStaticData('global');
st.items = st.items || {};
const tz = cfg.timezone;
const today = DateTime.now().setZone(tz).startOf('day');
const todayISO = today.toISODate();
const day = iso => DateTime.fromISO(iso, { zone: tz }).startOf('day');
const nice = iso => day(iso).toFormat(day(iso).year === today.year ? 'ccc LLL d' : 'ccc LLL d, yyyy');
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
const makeNonce = () => {
  const c = globalThis.crypto;
  if (c && c.getRandomValues) return Array.from(c.getRandomValues(new Uint8Array(12)), b => (b % 36).toString(36)).join('');
  return Array.from({ length: 12 }, () => Math.floor(Math.random() * 36).toString(36)).join('');
};

// A run that already happened today does nothing, so a second trigger never doubles the text.
if (st.last_run_day === todayISO) {
  return [{ json: { send: false, body: '', reason: 'already ran today', from: cfg.business_number, to: cfg.owner_cell } }];
}
st.last_run_day = todayISO;
const first = !st.started;

// Work out each item's current due date and how far away it is.
const live = [];
for (const it of items) {
  const mem = st.items[it.key] || {};
  let due = it.due;
  // A done link rolled this item forward. The rolled date stands until someone changes the
  // date in the list, and then the list wins, in either direction.
  if (mem.due && mem.list_due === it.due) due = mem.due;
  else if (mem.due) { delete mem.due; delete mem.list_due; }
  if (mem.done_for && mem.done_for !== due) delete mem.done_for;
  st.items[it.key] = mem;
  const days = Math.round(day(due).diff(today, 'days').days);
  live.push({ ...it, due, days, done: mem.done_for === due, mem });
}
// Forget items that are no longer on the list.
for (const k of Object.keys(st.items)) if (!items.some(it => it.key === k)) delete st.items[k];

const linkFor = x => {
  if (!cfg.done_links) return '';
  if (!x.mem.nonce || x.mem.nonce_due !== x.due) { x.mem.nonce = makeNonce(); x.mem.nonce_due = x.due; }
  return ' Done? ' + cfg.n8n_url + '/webhook/renewal-done?i=' + encodeURIComponent(x.key) + '&n=' + x.mem.nonce;
};
const when = x => x.days > 1 ? 'due in ' + x.days + ' days (' + nice(x.due) + ')'
  : x.days === 1 ? 'due tomorrow (' + nice(x.due) + ')'
  : x.days === 0 ? 'due today'
  : plural(-x.days, 'day') + ' overdue (was due ' + nice(x.due) + ')';

const due = live.filter(x => !x.done && (
  cfg.remind_days.includes(x.days) ||
  (x.days < 0 && cfg.overdue_every_days > 0 && (-x.days) % cfg.overdue_every_days === 0)));
const paragraphs = [];

if (first) {
  const next = live.filter(x => !x.done).sort((a, b) => a.days - b.days).slice(0, 3)
    .map(x => x.name + ' (' + (x.days < 0 ? 'overdue since ' + nice(x.due) : nice(x.due) + ', in ' + plural(x.days, 'day')) + ')');
  paragraphs.push('Renewal reminders are on for ' + cfg.business_name + '. Tracking ' + plural(live.length, 'item') + '.' +
    (next.length ? ' Next up: ' + next.join(', ') + '.' : '') +
    ' You get a text ' + cfg.remind_days.join(', ') + ' days before each one' +
    (cfg.monthly_outlook ? ', and on the 1st of each month a look at the next ' + cfg.outlook_days + ' days.' : '.'));
  st.started = todayISO;
}

if (due.length) {
  const lines = due.sort((a, b) => a.days - b.days).map(x => '- ' + x.name + ': ' + when(x) + '.' + (x.note ? ' ' + x.note.replace(/[.!?\s]+$/, '') + '.' : '') + linkFor(x));
  paragraphs.push('Renewals:\n' + lines.join('\n'));
}

if (cfg.monthly_outlook && (today.day === 1 || first)) {
  const soon = live.filter(x => !x.done && x.days >= 0 && x.days <= cfg.outlook_days && !due.includes(x))
    .sort((a, b) => a.days - b.days).map(x => x.name + ' ' + nice(x.due));
  if (soon.length && !first) paragraphs.push('Coming up in the next ' + cfg.outlook_days + ' days: ' + soon.join(', ') + '.');
  if (!soon.length && !due.length && !first) paragraphs.push('Nothing on your renewal list is due in the next ' + cfg.outlook_days + ' days.');
}

// Lines in the list that could not be read: said once, and again whenever they change.
const sig = problems.join('|');
if (problems.length && sig !== st.problem_sig) paragraphs.push('Check your renewal list:\n- ' + problems.join('\n- '));
st.problem_sig = sig;

// Anything Twilio would not take last time goes again, for up to 3 days.
st.unsent = (st.unsent || []).filter(u => day(u.day).diff(today, 'days').days > -3);
const all = [...st.unsent.map(u => u.text), ...paragraphs];
st.unsent = [...st.unsent, ...paragraphs.map(text => ({ text, day: todayISO }))];
let body = all.join('\n\n');
if (body.length > 1500) body = body.slice(0, 1480) + '... (cut short)';

return [{ json: {
  send: body.length > 0,
  body,
  from: cfg.business_number,
  to: cfg.owner_cell,
  first_run: first,
  reminded: due.map(x => x.key),
  tracked: live.length,
} }];

// The text went out, so nothing is waiting to be sent again.
$getWorkflowStaticData('global').unsent = [];
return [{ json: { delivered: true, sid: $json.sid } }];

// Runs when the owner taps a Done link, or the Undo link on the page that follows. A Done link
// must be the current one for that item: a repeating item rolls forward by its repeat, a one-time
// item is marked finished. The page says what changed and offers an Undo for a mistaken tap.
const { cfg, items, query } = $('Read your list').first().json;
const st = $getWorkflowStaticData('global');
st.items = st.items || {};
const tz = cfg.timezone;
const today = DateTime.now().setZone(tz).startOf('day');
const nice = iso => DateTime.fromISO(iso, { zone: tz }).toFormat('cccc, LLLL d, yyyy');
const esc = t => String(t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const makeNonce = () => {
  const c = globalThis.crypto;
  if (c && c.getRandomValues) return Array.from(c.getRandomValues(new Uint8Array(12)), b => (b % 36).toString(36)).join('');
  return Array.from({ length: 12 }, () => Math.floor(Math.random() * 36).toString(36)).join('');
};
const page = (title, text, undoUrl) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
  '<title>' + esc(title) + '</title></head><body style="font-family:system-ui,sans-serif;max-width:32rem;margin:3rem auto;padding:0 1.25rem;line-height:1.5;color:#1a1a1a">' +
  '<h1 style="font-size:1.4rem">' + esc(title) + '</h1><p style="font-size:1.1rem">' + esc(text) + '</p>' +
  (undoUrl ? '<p style="margin-top:2rem"><a href="' + esc(undoUrl) + '" style="color:#555">Tapped this by mistake? Undo</a></p>' : '') +
  '</body></html>';
const nothing = () => [{ json: { ok: false, html: page('Nothing changed', 'This link was already used, or the date has changed since it was sent. If something still needs updating, change its date in your renewal list.') } }];

const key = String(query.i || '');
const item = items.find(x => x.key === key);
const mem = st.items[key];
if (!item || !mem) return nothing();

// Undo: put the item back exactly as it was before the Done tap.
if (query.u) {
  if (!mem.undo || mem.undo.nonce !== String(query.u)) return nothing();
  const prev = mem.undo.prev;
  for (const k of ['due', 'list_due', 'done_for', 'nonce', 'nonce_due']) { if (prev[k] === undefined) delete mem[k]; else mem[k] = prev[k]; }
  delete mem.undo;
  const due = mem.due || item.due;
  return [{ json: { ok: true, key, undone: true, html: page('Undone: ' + item.name, 'It is back to due ' + nice(due) + ', and the reminders carry on as before.') } }];
}

const nonce = String(query.n || '');
if (!mem.nonce || !nonce || mem.nonce !== nonce) return nothing();
const prev = {};
for (const k of ['due', 'list_due', 'done_for', 'nonce', 'nonce_due']) if (mem[k] !== undefined) prev[k] = mem[k];
const was = mem.nonce_due;
delete mem.nonce;
delete mem.nonce_due;
mem.undo = { nonce: makeNonce(), prev };
const undoUrl = cfg.n8n_url + '/webhook/renewal-done?i=' + encodeURIComponent(key) + '&u=' + mem.undo.nonce;

if (item.repeat) {
  let next = DateTime.fromISO(was, { zone: tz });
  do { next = next.plus(item.repeat); } while (next <= today);
  mem.due = next.toISODate();
  mem.list_due = item.due;
  delete mem.done_for;
  // The first reminder for the new date is the earliest reminder day that is still ahead.
  const ahead = cfg.remind_days.map(d => next.minus({ days: d })).filter(d => d > today);
  const firstReminder = ahead.length ? ahead.reduce((a, b) => (b < a ? b : a)) : next;
  return [{ json: { ok: true, key, next: mem.due, first_reminder: firstReminder.toISODate(), html: page('Done: ' + item.name,
    'Next due ' + nice(mem.due) + '. The first reminder comes on ' + nice(firstReminder.toISODate()) + '. If that is not right, change the date in your renewal list and the list wins.', undoUrl) } }];
}
mem.done_for = was;
return [{ json: { ok: true, key, next: null, html: page('Done: ' + item.name,
  'No more reminders for it. It has no repeat, so when you get a chance, give it a new date or take it off your renewal list.', undoUrl) } }];
